// Which cycle to run. Week 18 is the best demo: the Amazon feed is
// missing that week, so exception path E2 fires.
const WEEK = 18;

return [{ json: { week: WEEK, caseId: 'AD-' + String(WEEK).padStart(3, '0') } }];

// S1 - DATA MONITOR AGENT: pull last week reported metrics.
// Falls back to the most recent valid week for any channel whose feed
// did not arrive (exception path E2).
const CHANNELS = ['google', 'meta', 'amazon'];
const BUDGET = 1150000;

const csv = $input.first().json.data;
const lines = csv.trim().split('\n');
const head = lines[0].split(',');
const rows = lines.slice(1).map(line => {
  const cells = line.split(',');
  const row = {};
  head.forEach((h, i) => { row[h] = cells[i]; });
  row.week = Number(row.week);
  row.share = Number(row.share);
  row.spend = Number(row.spend);
  row.clicks = Number(row.clicks);
  row.conversions = Number(row.conversions);
  row.feed_missing = String(row.feed_missing).toLowerCase() === 'true';
  return row;
});

const week = $('Open case').first().json.week;
const reportedWeek = week - 1;

const metrics = {};
const missingFeeds = [];
let usedFallback = false;

for (const channel of CHANNELS) {
  const thisWeek = rows.find(r => r.week === reportedWeek && r.channel === channel);
  if (!thisWeek) continue;

  if (thisWeek.feed_missing) {
    missingFeeds.push(channel);
    const fallback = rows
      .filter(r => r.channel === channel && r.week < reportedWeek && !r.feed_missing && r.clicks > 0)
      .sort((a, b) => a.week - b.week)
      .pop();
    if (fallback) {
      usedFallback = true;
      metrics[channel] = {
        week: fallback.week,
        cpc: fallback.spend / fallback.clicks,
        cvr: fallback.conversions / fallback.clicks,
        share: fallback.share,
        conversions: fallback.conversions,
        spend: fallback.spend,
        stale: true
      };
    }
    continue;
  }

  metrics[channel] = {
    week: reportedWeek,
    cpc: thisWeek.spend / thisWeek.clicks,
    cvr: thisWeek.conversions / thisWeek.clicks,
    share: thisWeek.share,
    conversions: thisWeek.conversions,
    spend: thisWeek.spend,
    stale: false
  };
}

// The split currently live is whatever ran last week.
const previousShares = {};
for (const channel of CHANNELS) {
  const row = rows.find(r => r.week === reportedWeek && r.channel === channel);
  previousShares[channel] = row ? row.share : 1 / 3;
}

const audit = [{
  stage: 'S1',
  tool: 'performance_db',
  summary: 'pulled week ' + reportedWeek + ' for ' + Object.keys(metrics).length +
    ' channels' + (missingFeeds.length ? '; no feed from ' + missingFeeds.join(', ') : '')
}];

return [{ json: {
  caseId: $('Open case').first().json.caseId,
  week, reportedWeek, metrics, missingFeeds, usedFallback,
  previousShares, history: rows, budget: BUDGET, audit, replans: 0
} }];

// S2 - DATA MONITOR AGENT: validate and detect anomalies.
//
// A flag needs the move to be BOTH larger than a fixed percentage AND
// unusual for that channel. Detection is on week-on-week CHANGE, not on
// distance from a trailing average, because these channels trend by
// design and a trend is not an anomaly.
const CHANNELS = ['google', 'meta', 'amazon'];
const CPC_SPIKE_PCT = 30, CVR_DROP_PCT = 30, LOOKBACK = 6;
const VOLATILITY_Z = 2.5, MIN_OBS = 3, ALPHA_HAT = 0.85;
const SHARE_REF = 1 / 3;

const d = $input.first().json;
const anomalies = [];

for (const channel of d.missingFeeds) {
  anomalies.push({
    channel, type: 'missing_feed', exception: 'E2',
    detail: 'No data feed from ' + channel + ' for week ' + d.reportedWeek + '.'
  });
}

const median = xs => {
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

for (const channel of CHANNELS) {
  if (d.missingFeeds.includes(channel) || !d.metrics[channel]) continue;

  const window = d.history
    .filter(r => r.channel === channel && r.week < d.reportedWeek &&
                 r.week >= d.reportedWeek - LOOKBACK && !r.feed_missing && r.clicks > 0)
    .sort((a, b) => a.week - b.week);
  if (window.length < 2) continue;

  // Observed conversion rate depends on how much was spent, because of
  // diminishing returns. Normalise every week to an equal-split spend so
  // our own budget moves do not look like channel anomalies. Observed CPC
  // needs no correction - spend cancels out of it exactly.
  const cpcSeries = window.map(r => r.spend / r.clicks);
  const cvrSeries = window.map(r =>
    (r.conversions / r.clicks) * Math.pow(r.share / SHARE_REF, 1 - ALPHA_HAT));

  const current = d.metrics[channel];
  const cvrNow = current.cvr * Math.pow(current.share / SHARE_REF, 1 - ALPHA_HAT);

  const checks = [
    { metric: 'cpc', value: current.cpc, series: cpcSeries, dir: 1,
      type: 'cpc_spike', label: 'CPC up', fixed: CPC_SPIKE_PCT },
    { metric: 'cvr', value: cvrNow, series: cvrSeries, dir: -1,
      type: 'cvr_collapse', label: 'conversion rate down', fixed: CVR_DROP_PCT }
  ];

  for (const c of checks) {
    const last = c.series[c.series.length - 1];
    if (!last || last <= 0) continue;

    const change = (c.value / last - 1) * 100;

    const priorChanges = [];
    for (let i = 1; i < c.series.length; i++) {
      priorChanges.push((c.series[i] / c.series[i - 1] - 1) * 100);
    }

    let bar = c.fixed, typicalMove = 0;
    if (priorChanges.length >= MIN_OBS) {
      const mid = median(priorChanges);
      const mad = median(priorChanges.map(x => Math.abs(x - mid)));
      typicalMove = 1.4826 * mad;
      bar = Math.max(c.fixed, VOLATILITY_Z * typicalMove);
    }

    if (c.dir * change >= bar) {
      anomalies.push({
        channel, type: c.type, exception: 'E1', change_pct: Math.round(change * 10) / 10,
        detail: channel + ' ' + c.label + ' ' + Math.abs(change).toFixed(0) +
          '% in one week, past the ' + bar.toFixed(0) + '% bar for this channel.'
      });
    }
  }
}

const degraded = d.missingFeeds.length > 0;
const audit = d.audit.concat([
  { stage: 'S2', tool: 'policy_kb', summary: 'retrieved rulebook v1.0: 15%-55% per channel, 15 pp weekly cap' },
  { stage: 'S2', tool: 'anomaly_checker', summary: anomalies.length ? anomalies.length + ' anomaly flag(s)' : 'no anomalies' },
  { stage: 'D1', tool: 'decision', summary: anomalies.length ? 'D1 = exception path' : 'D1 = clean week, proceed to propose' }
]);

return [{ json: { ...d, anomalies, degraded, hasAnomaly: anomalies.length > 0, audit } }];

// E1 / E2 - ORCHESTRATOR: handle the exception before planning.
//
// E1  a channel behaving abnormally is FROZEN at its current share and the
//     rest of the budget is re-planned around it.
// E2  a missing feed puts the case in degraded mode, which halves the
//     weekly shift cap, and queues a feed retry.
const d = $input.first().json;
const frozen = [];
const notes = [];

for (const a of d.anomalies) {
  if (a.exception === 'E1') {
    if (!frozen.includes(a.channel)) frozen.push(a.channel);
    notes.push('E1: ' + a.detail + ' Holding ' + a.channel + ' at ' +
      (d.previousShares[a.channel] * 100).toFixed(0) + '% and re-planning the rest.');
  } else if (a.exception === 'E2') {
    notes.push('E2: ' + a.detail + ' ' +
      (d.usedFallback ? 'Using the last valid week. ' : 'No earlier valid week. ') +
      'Case marked degraded, shift cap halved from 15 pp to 7.5 pp. Feed retry queued.');
  }
}

const audit = d.audit.concat([
  { stage: 'EXC', tool: 'decision', summary: 'Exception path taken: ' + notes.join(' | ') },
  { stage: 'EXC', tool: 'notifier', summary: 'notified marketing.manager@advantage.example: anomaly detected in week ' + d.week }
]);

return [{ json: { ...d, frozenChannels: frozen, escalations: notes, audit } }];

// S3 - ALLOCATION AGENT (reinforcement learning).
//
// Discounted Thompson Sampling over a Gamma-Poisson model of conversions
// per rupee. Conversions arrive as counts from spend, so the likelihood is
// Poisson; the conjugate prior for a Poisson rate is Gamma, so the update
// is exact arithmetic rather than a gradient step.
//
// discount = 0 means estimate from last week alone, which is what tuning
// on eight separate training worlds chose: channel advantage rotates, so
// older evidence is not merely less useful, it is misleading.
const CHANNELS = ['google', 'meta', 'amazon'];
const LAKH = 100000;
const CONCENTRATION = 3.0;
const DISCOUNT = 0.0;
const PRIOR_MEAN = 150, PRIOR_WEIGHT = 0.5;
const A0 = PRIOR_MEAN * PRIOR_WEIGHT, B0 = PRIOR_WEIGHT;

const d = $input.first().json;

// Marsaglia-Tsang gamma sampler.
function gammaSample(shape) {
  if (shape < 1) {
    return gammaSample(shape + 1) * Math.pow(Math.random(), 1 / shape);
  }
  const dd = shape - 1 / 3;
  const c = 1 / Math.sqrt(9 * dd);
  for (;;) {
    let x, v;
    do {
      const u1 = Math.random(), u2 = Math.random();
      x = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
      v = 1 + c * x;
    } while (v <= 0);
    v = v * v * v;
    const u = Math.random();
    if (u < 1 - 0.0331 * x * x * x * x) return dd * v;
    if (Math.log(u) < 0.5 * x * x + dd * (1 - v + Math.log(v))) return dd * v;
  }
}

// Build the posterior by replaying the reported weeks, decaying each time.
const posteriors = {};
for (const channel of CHANNELS) posteriors[channel] = { shape: A0, rate: B0 };

const weeks = [...new Set(d.history.filter(r => r.week < d.week).map(r => r.week))].sort((a, b) => a - b);
for (const w of weeks) {
  for (const channel of CHANNELS) {
    const p = posteriors[channel];
    p.shape = A0 + DISCOUNT * (p.shape - A0);
    p.rate = B0 + DISCOUNT * (p.rate - B0);
  }
  for (const channel of CHANNELS) {
    const row = d.history.find(r => r.week === w && r.channel === channel);
    if (!row || row.feed_missing) continue;
    posteriors[channel].shape += row.conversions;
    posteriors[channel].rate += row.spend / LAKH;
  }
}

// Thompson Sampling: one draw per channel, act as if it were the truth.
const sampled = {};
for (const channel of CHANNELS) {
  const p = posteriors[channel];
  sampled[channel] = gammaSample(p.shape) / p.rate;
}

const weights = {};
let totalWeight = 0;
for (const channel of CHANNELS) {
  weights[channel] = Math.pow(Math.max(sampled[channel], 1e-9), CONCENTRATION);
  totalWeight += weights[channel];
}

let target = {};
for (const channel of CHANNELS) target[channel] = weights[channel] / totalWeight;

// A rejection on a previous attempt pulls the re-plan back towards the
// status quo (exception path E4).
if (d.rejected) {
  const w = 0.5;
  let sum = 0;
  for (const channel of CHANNELS) {
    target[channel] = (1 - w) * target[channel] + w * d.previousShares[channel];
    sum += target[channel];
  }
  for (const channel of CHANNELS) target[channel] /= sum;
}

// A frozen channel does not move; the rest share what is left.
const frozen = d.frozenChannels || [];
if (frozen.length) {
  const held = {};
  let heldTotal = 0;
  for (const channel of frozen) { held[channel] = d.previousShares[channel]; heldTotal += held[channel]; }
  const movable = CHANNELS.filter(c => !frozen.includes(c));
  const freeWeight = movable.reduce((s, c) => s + target[c], 0);
  const out = { ...held };
  for (const channel of movable) out[channel] = (1 - heldTotal) * target[channel] / freeWeight;
  target = out;
}

const posteriorMeans = {};
for (const channel of CHANNELS) {
  posteriorMeans[channel] = Math.round(posteriors[channel].shape / posteriors[channel].rate * 10) / 10;
}

const audit = d.audit.concat([{
  stage: 'S3', tool: 'allocator',
  summary: 'Thompson Sampling proposed ' +
    CHANNELS.map(c => c + ' ' + (target[c] * 100).toFixed(0) + '%').join(', ')
}]);

return [{ json: { ...d, target, posteriorMeans, sampled, audit } }];

// S4 - GUARDRAIL AGENT. Deterministic, no model anywhere in it.
//
// The agent that proposes an allocation is never the agent that approves
// it. This checks the proposal against the rulebook and projects it onto
// the nearest compliant split that still sums to the whole budget. If no
// compliant split exists the week is infeasible and a human decides (E3).
const CHANNELS = ['google', 'meta', 'amazon'];
const MIN_SHARE = 0.15, MAX_SHARE = 0.55, MAX_SHIFT_PP = 15;
const BRAND_RULES = [{ id: 'BR02', channel: 'amazon', maxShare: 0.50 }];
const MATERIAL_TRIM_PP = 1.0;

const d = $input.first().json;
const degraded = d.degraded;
const cap = (MAX_SHIFT_PP / 100) * (degraded ? 0.5 : 1);
const frozen = d.frozenChannels || [];

// Effective floor and ceiling per channel.
const lo = {}, hi = {}, sources = ['hard_limits'];
for (const channel of CHANNELS) { lo[channel] = MIN_SHARE; hi[channel] = MAX_SHARE; }
for (const rule of BRAND_RULES) {
  hi[rule.channel] = Math.min(hi[rule.channel], rule.maxShare);
  sources.push(rule.id);
}
if (degraded) sources.push('degraded_mode');
for (const channel of CHANNELS) {
  lo[channel] = Math.max(lo[channel], d.previousShares[channel] - cap);
  hi[channel] = Math.min(hi[channel], d.previousShares[channel] + cap);
}
sources.push('weekly_shift_cap');
for (const channel of frozen) { lo[channel] = hi[channel] = d.previousShares[channel]; }
for (const channel of CHANNELS) { if (lo[channel] > hi[channel]) lo[channel] = hi[channel]; }

const floorSum = CHANNELS.reduce((s, c) => s + lo[c], 0);
const ceilSum = CHANNELS.reduce((s, c) => s + hi[c], 0);
const feasible = floorSum <= 1 + 1e-9 && ceilSum >= 1 - 1e-9;

// Record what the proposal broke before anything is changed.
const violations = [];
for (const channel of CHANNELS) {
  const share = d.target[channel];
  if (share < MIN_SHARE - 1e-9) violations.push(channel + ' at ' + (share * 100).toFixed(1) + '% is below the 15% floor.');
  if (share > MAX_SHARE + 1e-9) violations.push(channel + ' at ' + (share * 100).toFixed(1) + '% exceeds the 55% ceiling.');
  for (const rule of BRAND_RULES) {
    if (rule.channel === channel && share > rule.maxShare + 1e-9) {
      violations.push(rule.id + ': ' + channel + ' at ' + (share * 100).toFixed(1) + '% exceeds the ' + (rule.maxShare * 100).toFixed(0) + '% brand cap.');
    }
  }
  const moved = Math.abs(share - d.previousShares[channel]) * 100;
  if (moved > cap * 100 + 1e-6) {
    violations.push(channel + ' moves ' + moved.toFixed(1) + ' pp, above the ' + (cap * 100).toFixed(1) + ' pp cap.');
  }
}

// Project onto the feasible set: clip, then redistribute the remainder in
// proportion to the headroom each channel still has.
let proposal = {};
let trimNotes = [];
if (feasible) {
  for (const channel of CHANNELS) {
    proposal[channel] = Math.min(Math.max(d.target[channel], lo[channel]), hi[channel]);
  }
  for (let iteration = 0; iteration < 200; iteration++) {
    const total = CHANNELS.reduce((s, c) => s + proposal[c], 0);
    const residual = 1 - total;
    if (Math.abs(residual) < 1e-12) break;
    const headroom = {};
    let available = 0;
    for (const channel of CHANNELS) {
      headroom[channel] = residual > 0 ? hi[channel] - proposal[channel] : proposal[channel] - lo[channel];
      if (headroom[channel] > 0) available += headroom[channel];
    }
    if (available <= 1e-15) break;
    for (const channel of CHANNELS) {
      if (headroom[channel] > 0) proposal[channel] += residual * headroom[channel] / available;
      proposal[channel] = Math.min(Math.max(proposal[channel], lo[channel]), hi[channel]);
    }
  }
  for (const channel of CHANNELS) {
    const delta = (proposal[channel] - d.target[channel]) * 100;
    if (Math.abs(delta) > 0.05) {
      trimNotes.push(channel + ' trimmed by ' + (delta >= 0 ? '+' : '') + delta.toFixed(1) +
        ' pp to satisfy ' + sources.join(', ') + '.');
    }
  }
} else {
  proposal = { ...d.previousShares };
  trimNotes.push('No compliant split exists: floors sum to ' + (floorSum * 100).toFixed(1) +
    '% and ceilings to ' + (ceilSum * 100).toFixed(1) + '%.');
}

const trimmedPp = Math.max(...CHANNELS.map(c => Math.abs(proposal[c] - d.target[c]) * 100));
const wasTrimmed = trimmedPp >= MATERIAL_TRIM_PP;

const audit = d.audit.concat([
  { stage: 'S4', tool: 'constraint_calculator',
    summary: violations.length
      ? violations.length + ' violation(s), trimmed to ' + CHANNELS.map(c => c + ' ' + (proposal[c] * 100).toFixed(0) + '%').join(', ')
      : 'proposal already compliant' },
  { stage: 'D2', tool: 'decision',
    summary: feasible ? 'D2 = compliant after check' : 'D2 = infeasible, escalating (E3)' }
]);

return [{ json: { ...d, proposal, feasible, violations, trimNotes, wasTrimmed, audit } }];

// S5 - REPORTING AGENT: decide the autonomy level for this cycle and
// write the manager brief.
//
// Approval is required when the shift exceeds 5 pp, an anomaly is flagged,
// the proposal was materially trimmed, the week is running on stale data,
// OR the manager has already overridden this cycle. That last rule exists
// because without it the agent can answer a rejection with something small
// enough to slip under the threshold and move the budget without asking.
const CHANNELS = ['google', 'meta', 'amazon'];
const AUTO_EXECUTE_MAX_PP = 5, SLA_HOURS = 48;
const ESCALATE_TO = 'Senior Marketing Head';

const d = $input.first().json;

const shiftPp = Math.max(...CHANNELS.map(c =>
  Math.abs(d.proposal[c] - d.previousShares[c]) * 100));

const reasons = [];
if (shiftPp > AUTO_EXECUTE_MAX_PP + 1e-6) {
  reasons.push('largest shift ' + shiftPp.toFixed(1) + ' pp is above the ' + AUTO_EXECUTE_MAX_PP + ' pp auto-execute threshold');
}
if (d.anomalies.length) {
  reasons.push('anomaly flagged on ' + [...new Set(d.anomalies.map(a => a.channel))].join(', '));
}
if (d.wasTrimmed) reasons.push('proposal was trimmed by the guardrail agent');
if (d.degraded) reasons.push('the week is running on stale or incomplete data');
if (d.replans > 0) reasons.push('the manager has already overridden this cycle');

const route = reasons.length ? 'approve' : 'auto_execute';

const lines = [];
lines.push('Week ' + d.week + ' budget recommendation (' + d.caseId + ')');
lines.push('');
lines.push('Total for the week: Rs ' + d.budget.toLocaleString('en-IN'));
lines.push('');
lines.push('Proposed split:');
for (const channel of CHANNELS) {
  const was = d.previousShares[channel] * 100, now = d.proposal[channel] * 100;
  lines.push('  ' + channel.padEnd(8) + (was.toFixed(1) + '%').padStart(7) + ' -> ' +
    (now.toFixed(1) + '%').padStart(7) + '  (' + (now - was >= 0 ? '+' : '') +
    (now - was).toFixed(1) + ' pp)   recent performance ' + d.posteriorMeans[channel] + ' conversions per lakh');
}
lines.push('');
lines.push('Largest move: ' + shiftPp.toFixed(1) + ' pp (auto-execute threshold is ' + AUTO_EXECUTE_MAX_PP + ' pp).');
if (d.anomalies.length) {
  lines.push('');
  lines.push('Flagged this week:');
  for (const a of d.anomalies) lines.push('  - ' + a.detail);
}
if (d.frozenChannels && d.frozenChannels.length) {
  lines.push('  - Held frozen: ' + d.frozenChannels.join(', ') + '.');
}
if (d.wasTrimmed) {
  lines.push('');
  lines.push('Guardrail adjustments:');
  for (const n of d.trimNotes) lines.push('  - ' + n);
}
if (reasons.length) {
  lines.push('');
  lines.push('Why this needs your approval:');
  for (const r of reasons) lines.push('  - ' + r);
}
lines.push('');
lines.push('Reply approve / modify / reject within ' + SLA_HOURS + 'h, after which this escalates to ' +
  ESCALATE_TO + ' and the current split is held.');

const brief = lines.join('\n');

const audit = d.audit.concat([
  { stage: 'S5', tool: 'decision', summary: 'S5 route = ' + route + (reasons.length ? ' because ' + reasons.join('; ') : ' (within all thresholds)') }
].concat(route === 'approve'
  ? [{ stage: 'S5', tool: 'notifier', summary: 'notified marketing.manager@advantage.example: approval needed (' + shiftPp.toFixed(1) + ' pp shift)' }]
  : []));

return [{ json: { ...d, shiftPp, route, approvalReasons: reasons, brief, needsApproval: route === 'approve', audit } }];

// E4 / E5 - ORCHESTRATOR: act on what the manager said.
//
// approve  execute it
// reject   log the override and RE-PLAN (loops back to S3) with the
//          rejection as a new constraint, up to max_replans
// timeout  no reply within the SLA, so remind, escalate and hold
const MAX_REPLANS = 2;

const form = $input.first().json;
const d = $('S5 - Route for approval').first().json;

const decision = (form.Decision || form.decision || 'approve').toLowerCase();
const note = form.Note || form.note || '';
const replans = d.replans || 0;

let next, audit = d.audit.concat([
  { stage: 'S5', tool: 'decision', summary: 'Manager decision: ' + decision + (note ? '. ' + note : '') }
]);

if (decision === 'timeout') {
  next = 'hold';
  audit = audit.concat([
    { stage: 'E5', tool: 'notifier', summary: 'reminder sent: approval outstanding for 48h' },
    { stage: 'E5', tool: 'notifier', summary: 'escalated to Senior Marketing Head' },
    { stage: 'E5', tool: 'decision', summary: 'E5: SLA breached, holding the previous allocation' }
  ]);
} else if (decision === 'reject') {
  if (replans >= MAX_REPLANS) {
    next = 'hold';
    audit = audit.concat([{ stage: 'E4', tool: 'decision', summary: 'E4: ' + replans + ' re-plans already, holding rather than looping' }]);
  } else {
    next = 'replan';
    audit = audit.concat([{ stage: 'E4', tool: 'decision', summary: 'E4: rejection logged and fed back as a constraint; re-planning S3-S5 (attempt ' + (replans + 1) + ')' }]);
  }
} else {
  next = 'execute';
}

return [{ json: {
  ...d, managerDecision: decision, managerNote: note,
  replans: next === 'replan' ? replans + 1 : replans,
  rejected: next === 'replan', next, audit
} }];

// E3 - escalate: nothing complies, so a human decides. The agent does
// not guess, and it holds the previous allocation meanwhile.
const d = $input.first().json;
const audit = d.audit.concat([
  { stage: 'E3', tool: 'notifier', summary: 'escalated to Senior Marketing Head: no compliant allocation exists for this week' }
]);
return [{ json: { ...d, status: 'escalated', next: 'hold', escalations: (d.escalations || []).concat(['E3: no compliant allocation exists for this week']), audit } }];

// S6 - execute the approved split through the budget API.
const CHANNELS = ['google', 'meta', 'amazon'];
const d = $input.first().json;

const amounts = {};
for (const channel of CHANNELS) {
  amounts[channel] = Math.round(d.proposal[channel] * d.budget);
}

const audit = d.audit.concat([{
  stage: 'S6', tool: 'budget_api',
  summary: 'executed ' + CHANNELS.map(c => c + ' Rs ' + amounts[c].toLocaleString('en-IN')).join(', ')
}]);

return [{ json: { ...d, executed: d.proposal, amounts, status: 'executed', audit } }];

// Hold: the safe fallback. No budget moves.
const CHANNELS = ['google', 'meta', 'amazon'];
const d = $input.first().json;

const amounts = {};
for (const channel of CHANNELS) {
  amounts[channel] = Math.round(d.previousShares[channel] * d.budget);
}

const audit = d.audit.concat([{
  stage: 'HOLD', tool: 'decision',
  summary: 'Holding last week allocation unchanged. No budget moved.'
}]);

return [{ json: { ...d, executed: d.previousShares, amounts, status: d.status === 'escalated' ? 'escalated' : 'held', audit } }];

// S7 - feedback, audit log and the weekly report.
const CHANNELS = ['google', 'meta', 'amazon'];
const d = $input.first().json;

const moves = CHANNELS.map(c =>
  c + ' ' + (d.previousShares[c] * 100).toFixed(0) + '% -> ' + (d.executed[c] * 100).toFixed(0) + '%'
).join(', ');

const report = [];
report.push('Week ' + d.week + ' (' + d.caseId + ') - ' + d.status);
report.push('Allocation: ' + moves);
if (d.anomalies.length) report.push('Anomalies: ' + d.anomalies.map(a => a.detail).join('; '));
if (d.wasTrimmed) report.push('Guardrail: ' + d.trimNotes.join(' '));
if (d.approvalReasons && d.approvalReasons.length) report.push('Approval: ' + d.approvalReasons.join('; '));
if (d.escalations && d.escalations.length) report.push('Escalations: ' + d.escalations.join(' | '));

const audit = d.audit.concat([{
  stage: 'S7', tool: 'audit_logger', summary: 'Case closed as ' + d.status + '.'
}]);

return [{ json: {
  caseId: d.caseId,
  week: d.week,
  status: d.status,
  route: d.route,
  managerDecision: d.managerDecision || 'not required',
  replans: d.replans,
  shiftPp: d.shiftPp ? Number(d.shiftPp.toFixed(1)) : 0,
  anomalies: d.anomalies,
  frozenChannels: d.frozenChannels || [],
  degraded: d.degraded,
  executed: d.executed,
  amounts: d.amounts,
  weeklyReport: report.join('\n'),
  brief: d.brief,
  toolCalls: audit.filter(a => a.tool !== 'decision').length,
  auditTrail: audit
} }];
